                </thead>
                <tbody>
                    {filtered_logs.iter().enumerate().map(|(index, log)| {
                        let onclick = ctx.link().callback(move |_| Msg::SelectLogEntry(index));

                        html! {
                            <tr 
                                class={self.get_row_class(&log.severity)}
                                onclick={onclick}
                            >
