    #[tokio::test]
    async fn test_refresh_token_successful() {
        // Set up environment variables for JWT
        std::env::set_var("JWT_AUDIENCE", "test_aud");
        std::env::set_var("JWT_ISSUER", "test_issuer");

        let mock_user_repo = MockUserRepositoryTrait::new();
