    fn test_get_base_url_missing_environment() {
        let _guard = match ENV_MUTEX.lock() {
            Ok(guard) => guard,
            Err(poisoned) => {
                // Clear the poison and continue
                poisoned.into_inner()
            }
        };
        cleanup_test_env();

        // Don't set ENVIRONMENT
        let _base_url = EmailService::get_base_url();
    }

