    async fn update_verification_token(
        &self,
        user_id: Uuid,
        token: &str,
    ) -> Result<(), sqlx::Error> {
        debug!("Updating verification token for user: {}", user_id);
        let expires_at = Utc::now() + Duration::hours(24);

        sqlx::query!(
            r#"
            UPDATE users
            SET verification_token = $1,
                verification_token_expires_at = $2,
                updated_at = $3
            WHERE id = $4
