use std::future::Future;
use std::pin::Pin;
use std::time::Instant;

pub struct RequestLogger;

impl RequestLogger {
    pub fn new() -> Self {
        RequestLogger
    }
}

impl<S, B> Transform<S, ServiceRequest> for RequestLogger
where
    S: Service<ServiceRequest, Response = ServiceResponse<B>, Error = Error>,
    S::Future: 'static,
    B: 'static,
{
    type Response = ServiceResponse<B>;
    type Error = Error;
    type InitError = ();
    type Transform = RequestLoggerMiddleware<S>;
    type Future = Ready<Result<Self::Transform, Self::InitError>>;

    fn new_transform(&self, service: S) -> Self::Future {
        ok(RequestLoggerMiddleware { service })
    }
}

pub struct RequestLoggerMiddleware<S> {
    service: S,
}

impl<S, B> Service<ServiceRequest> for RequestLoggerMiddleware<S>
where
    S: Service<ServiceRequest, Response = ServiceResponse<B>, Error = Error>,
    S::Future: 'static,
    B: 'static,
{
    type Response = ServiceResponse<B>;
    type Error = Error;
    type Future = Pin<Box<dyn Future<Output = Result<Self::Response, Self::Error>>>>;

    fn poll_ready(&self, cx: &mut std::task::Context<'_>) -> std::task::Poll<Result<(), Self::Error>> {
        self.service.poll_ready(cx)
    }

    fn call(&self, req: ServiceRequest) -> Self::Future {
        let start_time = Instant::now();
        let method = req.method().clone();
        let path = req.path().to_string();
        let remote_addr = req.connection_info().peer_addr().unwrap_or("unknown").to_string();

        // Extract and clone header values to avoid lifetime issues
        let referer = if let Some(referer_header) = req.headers().get("Referer") {
            match referer_header.to_str() {
                Ok(val) => val.to_string(),
                Err(_) => "invalid".to_string(),
            }
        } else {
            "none".to_string()
        };

        let user_agent = if let Some(ua_header) = req.headers().get("User-Agent") {
            match ua_header.to_str() {
                Ok(val) => val.to_string(),
                Err(_) => "invalid".to_string(),
            }
        } else {
            "none".to_string()
        };

        let headers_count = req.headers().len();

        debug!(
            "Incoming request: {} {} from {} with {} headers, Referer: {}, User-Agent: {}",
            method,
            path,
            remote_addr,
            headers_count,
            referer,
            user_agent
        );

        let fut = self.service.call(req);

        Box::pin(async move {
            let response = fut.await?;
            let duration = start_time.elapsed();
            let status = response.status();

            // Log based on status code
            match status.as_u16() {
                200..=299 => {
                    info!(
                        "SUCCESS: {} {} {} [{}ms] from {} UA:\"{}\" Ref:\"{}\"",
                        method,
                        path,
                        status.as_u16(),
                        duration.as_millis(),
                        remote_addr,
                        user_agent,
                        referer
                    );
                }
                400..=499 => {
                    warn!(
                        "CLIENT ERROR: {} {} {} [{}ms] from {} UA:\"{}\" Ref:\"{}\"",
                        method,
                        path,
                        status.as_u16(),
                        duration.as_millis(),
                        remote_addr,
                        user_agent,
                        referer
                    );
                }
                500..=599 => {
                    warn!(
                        "SERVER ERROR: {} {} {} [{}ms] from {} UA:\"{}\" Ref:\"{}\"",
                        method,
                        path,
                        status.as_u16(),
                        duration.as_millis(),
                        remote_addr,
                        user_agent,
                        referer
                    );
                }
                _ => {
                    info!(
                        "OTHER: {} {} {} [{}ms] from {} UA:\"{}\" Ref:\"{}\"",
                        method,
                        path,
                        status.as_u16(),
                        duration.as_millis(),
                        remote_addr,
                        user_agent,
                        referer
                    );
                }
            }

            Ok(response)
        })
    }
}

